const j = $input.first().json;
let query, categories, excludeUserId, limit;

// Helper to parse a field that might be a JSON string like '{"query":"...","limit":8}'
function extractFromJsonOrString(val) {
  if (typeof val !== 'string' || !val.trim()) return { query: null, limit: null };
  const t = val.trim();
  if (t.startsWith('{')) {
    try {
      const p = JSON.parse(t);
      return {
        query: typeof p.query === 'string' && p.query.trim() ? p.query.trim() : null,
        limit: (p.limit !== null && p.limit !== undefined && Number.isFinite(Number(p.limit)) && Number(p.limit) > 0) ? Number(p.limit) : null
      };
    } catch {}
  }
  return { query: t, limit: null };
}

// Priority: input field > query field (either as plain text or JSON string)
if (j.input && typeof j.input === 'string' && j.input.trim()) {
  const parsed = extractFromJsonOrString(j.input);
  query = parsed.query;
  if (parsed.limit) limit = Math.max(1, Math.min(20, parsed.limit));
} else if (j.input && typeof j.input === 'object') {
  query = typeof j.input.query === 'string' && j.input.query.trim() ? j.input.query.trim() : null;
} else if (typeof j.query === 'string' && j.query.trim()) {
  // query field might contain a plain search string OR a JSON string
  const parsed = extractFromJsonOrString(j.query);
  query = parsed.query;
  if (parsed.limit) limit = Math.max(1, Math.min(20, parsed.limit));
} else {
  query = null;
}

if (!limit) {
  const rawLimit = j.limit;
  limit = (rawLimit !== null && rawLimit !== undefined && Number.isFinite(Number(rawLimit)) && Number(rawLimit) > 0)
    ? Math.max(1, Math.min(20, Number(rawLimit))) : 8;
}

categories = typeof j.categories === 'string' && j.categories.trim()
  ? j.categories.trim().split(',').map(c => c.trim().toLowerCase()).filter(Boolean)
  : null;

excludeUserId = typeof j.excludeUserId === 'string' && j.excludeUserId.trim() ? j.excludeUserId.trim() : null;

if (!query && !categories) {
  return [{ json: { books: [], count: 0, ids_for_bookIds: [], error: 'ERROR: query required. Call: search_catalog_books(input=JSON) where JSON has query field.' } }];
}

return [{ json: { query, categories, excludeUserId, limit } }];

// Normaliza y devuelve los libros encontrados como array JSON
const rows = $input.all();
const books = [];
const seen = new Set();

for (const row of rows) {
  const j = row.json;
  if (!j || j.error) continue;
  const id = Number(j.id);
  if (!Number.isFinite(id) || id <= 0 || seen.has(id)) continue;
  seen.add(id);
  books.push({
    id,
    title: j.title || '',
    author: j.author || '',
    description: j.description || null,
    coverUrl: j.coverUrl || null,
    categories: Array.isArray(j.categories) ? j.categories.filter(Boolean) : []
  });
}

const ids_for_bookIds = books.map(b => b.id);
return [{ json: { books, count: books.length, ids_for_bookIds } }];
